function decodeString(s) {
  while (s.includes("[")) {
    const close = s.indexOf("]");              // the first ] closes an innermost bracket
    const open = s.lastIndexOf("[", close);    // its partner: the last [ before it
    let start = open;
    while (start > 0 && s[start - 1] >= "0" && s[start - 1] <= "9") start--;   // the count's digits
    const k = Number(s.slice(start, open));
    const inner = s.slice(open + 1, close);
    s = s.slice(0, start) + inner.repeat(k) + s.slice(close + 1);   // rebuild the whole string
  }
  return s;
}

public String decodeString(String s) {
    while (s.indexOf('[') >= 0) {
        int close = s.indexOf(']');            // the first ] closes an innermost bracket
        int open = s.lastIndexOf('[', close);  // its partner: the last [ before it
        int start = open;
        while (start > 0 && Character.isDigit(s.charAt(start - 1))) start--;   // the count's digits
        int k = Integer.parseInt(s.substring(start, open));
        String inner = s.substring(open + 1, close);
        s = s.substring(0, start) + inner.repeat(k) + s.substring(close + 1);   // rebuild the whole string
    }
    return s;
}

string decodeString(string s) {
    size_t close;
    while ((close = s.find(']')) != string::npos) {   // the first ] closes an innermost bracket
        size_t open = s.rfind('[', close);            // its partner: the last [ before it
        size_t start = open;
        while (start > 0 && isdigit(s[start - 1])) start--;   // the count's digits
        int k = stoi(s.substr(start, open - start));
        string inner = s.substr(open + 1, close - open - 1);
        string repeated;
        for (int i = 0; i < k; i++) repeated += inner;
        s = s.substr(0, start) + repeated + s.substr(close + 1);   // rebuild the whole string
    }
    return s;
}

function decodeString(s) {
  const stack = [];                            // characters, and decoded pieces
  for (const c of s) {
    if (c !== "]") {
      stack.push(c);
      continue;
    }
    const parts = [];
    while (stack[stack.length - 1] !== "[") parts.push(stack.pop());   // pop back to the [
    stack.pop();                                                       // drop the [
    const inner = parts.reverse().join("");
    let digits = "";
    while (stack.length > 0 && stack[stack.length - 1] >= "0" && stack[stack.length - 1] <= "9") {
      digits = stack.pop() + digits;
    }
    stack.push(inner.repeat(Number(digits)));  // push the expansion back as one piece
  }
  return stack.join("");
}

def decode_string(s):
    stack = []                                 # characters, and decoded pieces
    for c in s:
        if c != "]":
            stack.append(c)
            continue
        parts = []
        while stack[-1] != "[":
            parts.append(stack.pop())          # pop back to the [
        stack.pop()                            # drop the [
        inner = "".join(reversed(parts))
        digits = []
        while stack and stack[-1].isdigit():
            digits.append(stack.pop())
        k = int("".join(reversed(digits)))
        stack.append(inner * k)                # push the expansion back as one piece
