public String decodeString(String s) {
    Deque<String> stack = new ArrayDeque<>();  // characters, and decoded pieces
    for (char c : s.toCharArray()) {
        if (c != ']') {
            stack.push(String.valueOf(c));
            continue;
        }
        List<String> parts = new ArrayList<>();
        while (!stack.peek().equals("[")) parts.add(stack.pop());   // pop back to the [
        stack.pop();                                                // drop the [
        Collections.reverse(parts);
        String inner = String.join("", parts);
        StringBuilder digits = new StringBuilder();
        while (!stack.isEmpty() && Character.isDigit(stack.peek().charAt(0))) digits.append(stack.pop());
        int k = Integer.parseInt(digits.reverse().toString());
        stack.push(inner.repeat(k));           // push the expansion back as one piece
    }
    StringBuilder out = new StringBuilder();
    while (!stack.isEmpty()) out.insert(0, stack.pop());
    return out.toString();
}

string decodeString(const string& s) {
    vector<string> st;                         // characters, and decoded pieces
    for (char c : s) {
        if (c != ']') {
            st.push_back(string(1, c));
            continue;
        }
        vector<string> parts;
        while (st.back() != "[") {             // pop back to the [
            parts.push_back(st.back());
            st.pop_back();
        }
        st.pop_back();                         // drop the [
        string inner;
        for (int i = (int)parts.size() - 1; i >= 0; i--) inner += parts[i];
        string digits;
        while (!st.empty() && isdigit(st.back()[0])) {
            digits += st.back();
            st.pop_back();
        }
        reverse(digits.begin(), digits.end());
        int k = stoi(digits);
        string repeated;
        for (int i = 0; i < k; i++) repeated += inner;
        st.push_back(repeated);                // push the expansion back as one piece
    }
    string out;
    for (const string& piece : st) out += piece;
    return out;
}

function decodeString(s) {
  const counts = [];       // how many times to repeat each open bracket
  const prefixes = [];     // the text built before each open bracket
  let cur = "";
  let k = 0;
  for (const c of s) {
    if (c >= "0" && c <= "9") {
      k = k * 10 + Number(c);              // numbers can have several digits
    } else if (c === "[") {
      counts.push(k);
      prefixes.push(cur);                  // park the text so far
      cur = "";
      k = 0;
    } else if (c === "]") {
      cur = prefixes.pop() + cur.repeat(counts.pop());
    } else {
      cur += c;
    }
  }
  return cur;
}

def decode_string(s):
    counts = []                  # how many times to repeat each open bracket
    prefixes = []                # the text built before each open bracket
    cur = []                     # the current bracket's text, as a list of pieces
    k = 0
    for c in s:
        if c.isdigit():
            k = k * 10 + int(c)          # numbers can have several digits
        elif c == "[":
            counts.append(k)
            prefixes.append(cur)         # park the text so far
            cur = []
            k = 0
        elif c == "]":
            inner = "".join(cur)
            cur = prefixes.pop()
            cur.append(inner * counts.pop())
        else:
            cur.append(c)
    return "".join(cur)

public String decodeString(String s) {
    Deque<Integer> counts = new ArrayDeque<>();          // how many times to repeat each open bracket
    Deque<StringBuilder> prefixes = new ArrayDeque<>();  // the text built before each open bracket
    StringBuilder cur = new StringBuilder();
    int k = 0;
    for (char c : s.toCharArray()) {
        if (Character.isDigit(c)) {
            k = k * 10 + (c - '0');                      // numbers can have several digits
        } else if (c == '[') {
            counts.push(k);
            prefixes.push(cur);                          // park the text so far
            cur = new StringBuilder();
            k = 0;
        } else if (c == ']') {
            String inner = cur.toString();
            cur = prefixes.pop();
            cur.append(inner.repeat(counts.pop()));
        } else {
            cur.append(c);
        }
    }
    return cur.toString();
}

string decodeString(const string& s) {
    stack<int> counts;                 // how many times to repeat each open bracket
    stack<string> prefixes;            // the text built before each open bracket
    string cur;
    int k = 0;
    for (char c : s) {
        if (isdigit(c)) {
            k = k * 10 + (c - '0');            // numbers can have several digits
        } else if (c == '[') {
            counts.push(k);
            prefixes.push(cur);                // park the text so far
            cur.clear();
            k = 0;
        } else if (c == ']') {
            string inner = cur;
            cur = prefixes.top();
            prefixes.pop();
            for (int i = counts.top(); i > 0; i--) cur += inner;
            counts.pop();
        } else {
            cur += c;
        }
    }
    return cur;
}
